const TZ_BY_CALLING_CODE = [
  ['+57', 'America/Bogota'], ['+52', 'America/Mexico_City'], ['+34', 'Europe/Madrid'], ['+44', 'Europe/London'],
  ['+54', 'America/Argentina/Buenos_Aires'], ['+56', 'America/Santiago'], ['+51', 'America/Lima'], ['+593', 'America/Guayaquil'],
